def _version_time_label() -> str:
    times = []
    for fp in (ROOT / 'VERSION.json', ROOT / 'setup.py'):
        try:
            times.append(fp.stat().st_mtime)
        except OSError:
            pass
    if not times:
        return "unknown"
    return datetime.datetime.fromtimestamp(max(times)).isoformat(timespec="seconds")


